// ClientsPage.jsx
import { useState } from "react";
import ClientsList from "../ClientsList/ClientsList";
import InvoiceSummary from "../Clients/Clients";
import ProfitabilityResults from "../ProfitabilityResults/ProfitabilityResults";

function ClientsPage() {
  const [selectedClient, setSelectedClient] = useState(null);

  return (
    <>
      <ClientsList onClientSelect={setSelectedClient} />

      <InvoiceSummary client={selectedClient} />

      <ProfitabilityResults client={selectedClient} />
    </>
  );
}

export default ClientsPage;
